			 * previous loop walk, which is not needed anymore.
			 */
			iput(prev_inode);
			if (prev_detached)
				iput(prev_inode);
			cond_resched();
			spin_lock(&sb->s_inode_list_lock);
		}
		prev_inode = inode;
		prev_detached = detached;
	}
	spin_unlock(&sb->s_inode_list_lock);

	/* Puts the inode reference from the last loop walk, if any. */
	if (prev_inode) {
		iput(prev_inode);
		if (prev_detached)
			iput(prev_inode);
